import socket
s=socket.create_connection(('127.0.0.2',6667),timeout=5)
s.settimeout(3)
try:
    print('banner:',s.recv(4096))
except Exception as e: print('no banner',e)
s.sendall(b'NICK recon\nUSER recon 0 * :recon\n')
import time
time.sleep(2)
try:
    print('resp:',s.recv(8192))
except Exception as e: print('err',e)
s.sendall(b'LIST\n')
time.sleep(2)
try:
    print('list:',s.recv(8192))
except Exception as e: print('err',e)
"
